-- =====================================================================================
-- Reformulação regulatória 2026-09-16 — ZMA (Zinco, Magnésio e Vitamina B6) (zma-zinco-magnesio-e-vitamina-d)
-- Fragmento PL/pgSQL idempotente, casando por SLUG (nunca UUID), no estilo de
-- supabase/migrations/20260920000000_composicoes_conforme_rotulo.sql.
-- Fonte: docs/conformidade/reformulacao/zma-zinco-magnesio-e-vitamina-d.md e scratchpad/fase2/zma-zinco-magnesio-e-vitamina-d.json.
-- Sem guarda de contagem aqui (a consolidação põe); só o bloco deste produto.
-- NÃO APLICADO em nenhum banco. Veredito esperado: CONFORME CONDICIONADO A (laudo de origem Camellia sinensis da L-teanina nova; laudo novo do bisglicinato de magnésio; aquisição de tetraborato de sódio decahidratado ou frutoborato de cálcio com laudo)
-- =====================================================================================

-- 1. exclusão lógica das composições ativas atuais desta fórmula
update public.formula_compositions fc
set active = false, deleted_at = now(), reason_deleted = 'reformulação regulatória 2026-09-16'
from public.formulas f
where f.id = fc.formula_id and f.deleted_at is null and f.slug = 'zma-zinco-magnesio-e-vitamina-d'
  and fc.deleted_at is null
  and coalesce(fc.metadata->>'fonte', '') <> 'reformulacao_2026-09-16';

-- 2. inserção das composições reformuladas (ingredient_id resolvido por slug; só se ainda não houver linha desta fonte)
insert into public.formula_compositions (formula_id, ingredient_name, quantity, unit, sort_order, ingredient_id, metadata)
select f.id, v.ingredient_name, v.quantity, v.unit::public.composition_unit, v.sort_order, i.id, v.metadata::jsonb
from (values
    ('zma-zinco-magnesio-e-vitamina-d', 0, 'Magnésio (bisglicinato de magnésio)', 151.1, 'mg', 'magnesio', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Magnésio", "forma_insumo": "Bisglicinato de magnésio (laudo: ''Magnésio Glicinato 30%'', CAS 14783-68-7)", "massa_insumo_mg": 500.0, "laudo_lote": "90844 (Analitic, fabricante 66342023062230)", "laudo_validade": "21/06/2025", "laudo_vencido": true, "teor_pct": 30.22, "teor_fonte": "laudo vencido", "ativo_mg": 151.1, "unidade_ativo": "mg", "minimo": 63, "maximo": 350, "pct_do_maximo": 43.17, "linha_anexo": "I·Bisglicinato de magnésio; III/IV·Magnésio", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (500 mg de sal = 152 mg de Mg declarados; 43,2% do teto); forma autorizada; os dois laudos de bisglicinato 30% da máquina (90844 e 088629) estão vencidos — pedir laudo novo do lote em estoque ou lote novo e recalcular a massa pelo teor."}'),
    ('zma-zinco-magnesio-e-vitamina-d', 1, 'L-teanina de folhas de Camellia sinensis', 150, 'mg', 'l-teanina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Teanina", "forma_insumo": "L-teanina de folhas de Camellia sinensis — insumo a adquirir (rota B)", "massa_insumo_mg": 150.0, "laudo_lote": "AUTO039250 (Lepuge, fabricante 202408145) — SÍNTESE QUÍMICA, não serve", "laudo_validade": "13/08/2027", "laudo_vencido": false, "teor_pct": 100.0, "teor_fonte": "assumido", "ativo_mg": 150, "unidade_ativo": "mg", "minimo": 50, "maximo": 250, "pct_do_maximo": 60.0, "linha_anexo": "I·L-teanina de folhas de Camellia sinensis (IN 318/2024); III/IV·Teanina", "status": "forma trocada (origem) — PENDENTE laudo", "e_sal": false, "observacao": "o rótulo destaca a L-teanina na chamada principal (''a união de zinco, magnésio, vitamina D3 e L-teanina''); mantém-se a dose (60% do teto) trocando a origem: só a de folhas de Camellia sinensis é autorizada (especificação aprovada: Blue California, painel ANVISA lido em 15/09). Rota A (retirar) registrada na seção 8."}'),
    ('zma-zinco-magnesio-e-vitamina-d', 2, 'Zinco (bisglicinato de zinco)', 15, 'mg', 'zinco', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Zinco", "forma_insumo": "Bisglicinato de zinco (CAS 14281-83-5)", "massa_insumo_mg": 75.4148, "laudo_lote": "055-ZN/25 (Galena, CIQ 2505027507)", "laudo_validade": "06/05/2027", "laudo_vencido": false, "teor_pct": 19.89, "teor_fonte": "laudo", "ativo_mg": 15, "unidade_ativo": "mg", "minimo": 1.65, "maximo": 29.59, "pct_do_maximo": 50.69, "linha_anexo": "I·Bisglicinato de zinco; III/IV·Zinco", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (50,7% do teto); laudo válido."}'),
    ('zma-zinco-magnesio-e-vitamina-d', 3, 'Boro (tetraborato de sódio decahidratado)', 3, 'mg', 'boro', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Boro", "forma_insumo": "Tetraborato de sódio decahidratado (CAS 1303-96-4) — insumo a adquirir", "massa_insumo_mg": 26.459, "laudo_lote": null, "laudo_validade": null, "laudo_vencido": null, "teor_pct": 11.34, "teor_fonte": "assumido", "ativo_mg": 3, "unidade_ativo": "mg", "minimo": null, "maximo": 8.866, "pct_do_maximo": 33.84, "linha_anexo": "I·Tetraborato de sódio decahidratado (IN 76/2020); III·Boro NE; IV·Boro 8,866 mg", "status": "forma trocada", "e_sal": false, "observacao": "''quelato de boro (glicinato de boro)'' 56,6 mg não é forma do Anexo I; os dois laudos de boro da máquina (044951 e 91125) são do mesmo glicinato sintético. Dose mantida em 3 mg (33,8% do teto) — o rótulo não declara o elemento; passa a declarar."}'),
    ('zma-zinco-magnesio-e-vitamina-d', 4, 'Vitamina B6 (cloridrato de piridoxina)', 1.3, 'mg', 'vitamina-b6', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina B6", "forma_insumo": "Cloridrato de piridoxina (CAS 58-56-0)", "massa_insumo_mg": 1.5817, "laudo_lote": "91188 (Analitic, fabricante 241229T092)", "laudo_validade": "28/12/2027", "laudo_vencido": false, "teor_pct": 99.9, "teor_fonte": "laudo", "ativo_mg": 1.3, "unidade_ativo": "mg", "minimo": 0.26, "maximo": 98.6, "pct_do_maximo": 1.32, "linha_anexo": "I·Cloridrato de piridoxina; III/IV·Vitamina B6", "status": "mantido", "e_sal": false, "observacao": "1,3 mg de vitamina B6 (1,3% do teto). O rótulo hoje trata 1,3 mg de cloridrato como se fosse B6 pura (o memorial rev02 já marca como correção obrigatória: entrega real 1,07 mg); a massa sobe para 1,58 mg para entregar 1,3 mg de piridoxina."}'),
    ('zma-zinco-magnesio-e-vitamina-d', 5, 'Vitamina D3 (colecalciferol)', 25, 'mcg', 'vitamina-d', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina D", "forma_insumo": "Vitamina D3 (colecalciferol), pó 100.000 UI/g (CAS 67-97-0)", "massa_insumo_mg": 8.6957, "laudo_lote": "91408 (Analitic, fabricante 2025111601)", "laudo_validade": "15/11/2028", "laudo_vencido": false, "teor_pct": null, "teor_fonte": "laudo", "ativo_mg": 0.025, "unidade_ativo": "µg", "minimo": 3, "maximo": 50.0, "pct_do_maximo": 50.0, "linha_anexo": "I·Vitamina D3 (Colecalciferol); III/IV·Vitamina D", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (50,0% do teto; 167% do VD); laudo válido."}'),
    ('zma-zinco-magnesio-e-vitamina-d', 6, 'Dióxido de silício (INS 551)', 237.849, 'mg', 'dioxido-de-silicio', '{"fonte": "reformulacao_2026-09-16", "excipiente": true, "ins": "551", "observacao": "q.s.p. 1.000 mg — quantum satis (IN 211/2023, 14.2, auditoria de 15/09). Continua sendo fração alta (a auditoria já apontou 21,7% como ''enchimento''); ver pendência 5."}')
) as v(slug, sort_order, ingredient_name, quantity, unit, ingredient_slug, metadata)
join public.formulas f on f.slug = v.slug and f.deleted_at is null
join public.ingredients i on i.slug = v.ingredient_slug and i.deleted_at is null
where not exists (
    select 1 from public.formula_compositions x
    where x.formula_id = f.id and x.deleted_at is null and x.metadata->>'fonte' = 'reformulacao_2026-09-16'
);

